// Normalize GitHub push or manual webhook into branch_name + commit messages.
// Skip patterns (filtered by IF "No es una referencia de tag"):
//   - chore(release)  → avoid release loop after standard-version push
//   - multi-locale twins progress / auto multi-locale twins → goal auto-commit bots
const out = [];
const SKIP_RE = /chore\(release\)|multi-locale\s+twins\s+progress|auto\s+multi-locale\s+twins/i;

for (const item of $input.all()) {
  const j = item.json;
  // Manual webhook body: { branch: "master" } or { ref: "refs/heads/master" }
  let ref = j.body?.ref || j.ref || (j.body?.branch ? `refs/heads/${j.body.branch}` : null);
  if (!ref && j.body?.branch_name) ref = `refs/heads/${j.body.branch_name}`;
  // Default to typescript-migration for bare webhook pings (product branch)
  if (!ref && (j.headers || j.query)) ref = "refs/heads/typescript-migration";
  if (!ref || !String(ref).startsWith("refs/heads/")) continue;

  item.json.branch_name = String(ref).split("refs/heads/")[1];
  const staticData = $getWorkflowStaticData("global");
  staticData.branch_name = item.json.branch_name;

  const body = j.body || {};
  const commits = body.commits || j.commits || [];
  const commitMsgs = commits.map((c) => c?.message || "").filter(Boolean);
  const headMsg =
    body.head_commit?.message ||
    j.head_commit?.message ||
    body.message ||
    commitMsgs[0] ||
    "";

  item.json.head_commit_message = headMsg;
  item.json.all_commit_messages = commitMsgs.length
    ? commitMsgs.join("\n---\n")
    : headMsg;

  // skip if head matches, or every commit in the push is skippable (bot-only push)
  const headSkip = SKIP_RE.test(headMsg);
  const allSkip =
    commitMsgs.length > 0 && commitMsgs.every((m) => SKIP_RE.test(m));
  item.json.skip_ci = headSkip || allSkip;
  item.json.skip_ci_flag = (headSkip || allSkip) ? 'yes' : 'no';
  item.json.skip_ci_reason = headSkip
    ? "head_commit matches skip pattern"
    : allSkip
      ? "all commits match skip pattern"
      : "";

  out.push(item);
}

// Manual empty webhook → allow build on default branch (not skip)
return out.length
  ? out
  : [
      {
        json: {
          branch_name: "typescript-migration",
          head_commit_message: "manual",
          all_commit_messages: "manual",
          skip_ci: false,
          skip_ci_flag: 'no',
          skip_ci_reason: '',
        },
      },
    ];

const data = $input.first().json;
const out = (data.stdout || "") + "\n" + (data.stderr || "");
if (!out.includes("::DOCVAT_BUILD_DONE::")) {
  throw new Error("Build sidecar finished without ::DOCVAT_BUILD_DONE:: marker (false success blocked)");
}
const m = out.match(/::DOCVAT_VERSION::(v[\d.]+)/);
const done = out.match(/::DOCVAT_BUILD_DONE::(v[\d.]+)/);
data.app_version = (done && done[1]) || (m && m[1]) || "desconocida";
data.build_ok = true;
return data;

