// Canonical branch for this build cycle (supports requeue loop).
const sd = $getWorkflowStaticData('global');
const input = $input.first().json || {};
const defaultBranch = "typescript-migration";
const branch = input.branch_name || sd.branch_name || defaultBranch;
sd.branch_name = branch;
// Each new attempt clears the failure flag; error path sets it again if needed.
sd.last_build_failed = false;
return [{
  json: {
    branch_name: branch,
    build_action: input.build_action || 'run',
  },
}];

// Mark this attempt as failed so Cola: release can stopAndError if no pending rebuild.
const sd = $getWorkflowStaticData('global');
sd.last_build_failed = true;
const input = $input.first().json || {};
return [{ json: { ...input, last_build_failed: true } }];

// Parse Cola: acquire shell JSON + mirror into workflow staticData.
const raw = String($input.first().json.stdout || '').trim();
let result;
try { result = JSON.parse(raw); }
catch (e) {
  throw new Error('Cola: acquire: invalid JSON from mutex script: ' + raw.slice(0, 300));
}
const sd = $getWorkflowStaticData('global');
const branch = result.branch_name;
sd.branch_name = branch;
sd.pending_branch = branch;
sd.build_busy = result.build_action === 'run';
sd.build_pending = result.build_action === 'queued';
if (result.build_action === 'run') sd.build_started_at = Date.now();
return [{ json: result }];

// Pass last_build_failed into the shell release script.
const sd = $getWorkflowStaticData('global');
const input = $input.first().json || {};
return [{
  json: {
    ...input,
    ci_failed: !!sd.last_build_failed,
  },
}];

// Parse Cola: release shell JSON + clear local busy/fail flags when not rerunning.
const raw = String($input.first().json.stdout || '').trim();
let result;
try { result = JSON.parse(raw); }
catch (e) {
  throw new Error('Cola: release: invalid JSON from mutex script: ' + raw.slice(0, 300));
}
const sd = $getWorkflowStaticData('global');
sd.branch_name = result.branch_name || sd.branch_name;
sd.pending_branch = result.branch_name || sd.pending_branch;
if (result.build_action === 'rerun') {
  sd.build_busy = true;
  sd.build_pending = false;
  sd.build_started_at = Date.now();
} else {
  sd.build_busy = false;
  sd.build_pending = false;
  sd.build_started_at = null;
  sd.last_build_failed = false;
}
// normalize boolean for IF nodes
result.nudge_other = result.nudge_other === true || result.nudge_other === 'true';
return [{ json: result }];
